igue","slug":"subscription-fatigue","created_at":"2026-10-06T02:49:38.03521+00:00","updated_at":"2026-10-06T02:49:38.03521+00:00","description":"The user wants useful core functionality without another mandatory recurring subscription."}],"where":"id IN ('58231e35-9b9b-46bb-add8-21417ed2c6d1')","preserveWhere":"id IN ('58231e35-9b9b-46bb-add8-21417ed2c6d1')"},{"table":"audiences","rows":[{"id":"6c4f55ba-6a76-4b4e-aab3-2913750f8dd1","name":"Writers and Editors","slug":"writers-and-editors","created_at":"2026-10-06T04:14:23.31324+00:00","updated_at":"2026-10-06T04:14:23.31324+00:00","description":"People comparing grammar, style, or language-reference tools within the documented edition and language scope."}],"where":"id IN ('6c4f55ba-6a76-4b4e-aab3-2913750f8dd1')","preserveWhere":"id IN ('6c4f55ba-6a76-4b4e-aab3-2913750f8dd1')"},{"table":"escape_routes","rows":[{"id":"e0170d70-5f76-4d56-b541-858ec84a0f19","name":"Grammarly Alternatives Without a Subscription","slug":"grammarly-alternatives-without-a-subscription","status":"published","anchor_id":"0270dd80-f9fb-4c10-8937-3928c4ae4362","created_at":"2026-10-15T07:04:33.158474+00:00","updated_at":"2026-10-15T07:04:33.158474+00:00","description":"Options for reviewing English passive constructions without a mandatory recurring software payment for the reviewed access path. Compare the bounded task of inspecting feedback, manually revising and rechecking against Grammarly Pro capability. Not a complete Grammarly or automatic rewrite replacement; account, usage limits and service conditions apply.","last_verified_at":"2026-10-15T00:00:00+00:00","editorially_approved":true}],"where":"slug IN ('privacy-friendly-grammarly-alternatives','grammarly-alternatives-without-a-subscription')","preserveWhere":"slug='grammarly-alternatives-without-a-subscription'"},{"table":"escape_route_products","rows":[{"position":2,"created_at":"2026-10-15T07:04:33.158474+00:00","product_id":"f6150c8b-5485-4f65-b769-a27b6f50af66","updated_at":"2026-10-15T07:04:33.158474+00:00","novelty_score":null,"quality_score":null,"editorial_note":null,"escape_route_id":"e0170d70-5f76-4d56-b541-858ec84a0f19","relevance_score":null,"constraint_fit_score":null},{"position":1,"created_at":"2026-10-15T07:04:33.158474+00:00","product_id":"964e1139-e9ce-4b9a-93eb-e4cf43ad2a02","updated_at":"2026-10-15T07:04:33.158474+00:00","novelty_score":null,"quality_score":null,"editorial_note":null,"escape_route_id":"e0170d70-5f76-4d56-b541-858ec84a0f19","relevance_score":null,"constraint_fit_score":null},{"position":3,"created_at":"2026-10-15T07:04:33.158474+00:00","product_id":"8fff305e-bbbf-4b61-80c7-0f2dcffc68ad","updated_at":"2026-10-15T07:04:33.158474+00:00","novelty_score":null,"quality_score":null,"editorial_note":null,"escape_route_id":"e0170d70-5f76-4d56-b541-858ec84a0f19","relevance_score":null,"constraint_fit_score":null}],"where":"escape_route_id IN (SELECT id FROM software_discovery.escape_routes WHERE slug='grammarly-alternatives-without-a-subscription')","preserveWhere":"escape_route_id IN (SELECT id FROM software_discovery.escape_routes WHERE slug='grammarly-alternatives-without-a-subscription')"},{"table":"escape_route_products","rows":[],"where":"product_id IN ('92f86c9d-d0b5-46b2-a831-d6f366a80e2f')","preserveWhere":"product_id IN ('92f86c9d-d0b5-46b2-a831-d6f366a80e2f')"}]}$payload$::jsonb;
  op jsonb; raw_row jsonb; row_data jsonb; replacement jsonb; own jsonb;
  t text; cols text; conflict_cols text; key_condition text; match_condition text;
  assignments text; changed text; statement text; allowed boolean; bad boolean; found_row boolean;
  route_slug text; route_id uuid; wanted text[]; desired_keys text[]; prefix text;
  expected integer; actual integer; where_data jsonb; fragment_id uuid;
  k text; v jsonb; target_table text; target_key text; target_value text; resolved_id uuid; input_data jsonb;
BEGIN
  PERFORM set_config('lock_timeout','10s',true);
  PERFORM pg_advisory_xact_lock(7232003);
  LOCK TABLE software_discovery.evidence_sources,software_discovery.anchors,software_discovery.attributes,software_discovery.problems,software_discovery.audiences,software_discovery.products,software_discovery.product_attributes,software_discovery.product_anchors,software_discovery.product_problems,software_discovery.product_audiences,software_discovery.claim_evidence,software_discovery.product_attribute_evidence,software_discovery.product_anchor_evidence,software_discovery.product_problem_evidence,software_discovery.product_audience_evidence,software_discovery.escape_routes,software_discovery.escape_route_products IN SHARE ROW EXCLUSIVE MODE;

  PERFORM set_config('TimeZone','UTC',true);
  IF EXISTS(SELECT 1 FROM software_discovery.attributes WHERE slug IN ('privacy-friendly','reviewed-local-operation')) THEN RAISE EXCEPTION 'PR5.102 new taxonomy collision'; END IF;
  IF EXISTS(SELECT 1 FROM software_discovery.escape_routes WHERE slug IN ('privacy-friendly-grammarly-alternatives')) THEN RAISE EXCEPTION 'PR5.102 route collision or repeated apply; obtain fresh snapshot'; END IF;
  IF EXISTS(SELECT 1 FROM software_discovery.evidence_sources WHERE seed_key LIKE 'privacy99-%') OR EXISTS(SELECT 1 FROM software_discovery.claim_evidence WHERE seed_key IN ('seed-claim:0cb2cb46e42a90a2d6ef637b0f05be2162bf3a5d45f5a8a2ac8b748e1a7cbc1a','seed-claim:181922eff4723f0b9a6dc3b5062ad1f081d50283ff5d2c3cf16e8becb0d8b66b','seed-claim:258c7a52a349c3cee143f29215e35d90f8cad97b3a6b89f2aa3563a69dcf8050','seed-claim:28393d4f0dc911f8c33b425252448113aa2d763dbfaaeb1beaae777be9ac93ca','seed-claim:2ade1a64d75a4f5fddd16d46789a58fe36a90cf3ee2c18ff5d6c0cbcc4a77640','seed-claim:3ca05835808d2d700ce2d119ab78ca523c8502a307b325641c085de78b514ffb','seed-claim:3ff53769f5abb72fc6753f5d04d2676c5f22f8ef701428bd9aaa11cff7430ecc','seed-claim:59d7633adc02cf78dc7f9295f91c062cf12e5bcaa383e1eee546de5f3591a2b9','seed-claim:63e7bd49a9188ff29e801cf296c42864590fa18ab9b449d985da4e9c269a1b6c','seed-claim:65175abf98aa78fbc8035e644e014627fec0d7d5aafebaa73b2a6295214a137b','seed-claim:69c37d4ca1c6cb3638440de0c3bcd95430d192ad375d9775178b39e026e0ae86','seed-claim:77c2c8789321a2217f7b6ba9dd57a86b00c5363f96d4d9ecade9e8ecb0b23b94','seed-claim:810c4519869ecd7653c4c899cec737099f9c0cc2aad45e5c27f8c2da73c53702','seed-claim:837caf1c4ba6ecca7bd58c533d348cb4d3e66d9b59907aa5fb6969ce97ac6232','seed-claim:881ef5e2daeb4a803525ad62e439c91ba8ae1ec93dc0338cbd46809ae9e5120e','seed-claim:8ae48e57e247f1b895b96bf03d840843a673511ea3f90249a2d55b047ee228da','seed-claim:8d94d721b1c3feaf3726f89554d3da66e4c14bb1063b6935f4ed059614e9e28a','seed-claim:925d731e783ce50454fd8c70cf0dd3462b46f79c707959c60c1a6d7324164dc5','seed-claim:9d17cfcc3be38e165e0d58756e00746cdde8ebdf60349467513986f8aafb0ab6','seed-claim:a11c7f148587fb3d984e7276eb66b3cea1e5bd2dc25ee44a061d36b77650f991','seed-claim:a1aaf4a2ba4bab300f8036341e4fbd63b2f2501e762695c9e76c1e46c7f52616','seed-claim:a953ea23841b7006424316ff3b3e04930883afd6cb848241fbe61ef739e4f02e','seed-claim:aff1a6d6872dfe380eeb0e3d3c0f51b87fb46ea4c934dfc4f5c76ca4e19e398d','seed-claim:b82f3a4b1bcab18a4bb9c30352ff9e9256898f0260870b03c43bd06e5de352f9','seed-claim:bb7c005296989fc8098fa3cb0f15719e40269876dc4011ca3a84041b59cbfaed','seed-claim:ce0e824294ab0c40abfbd1e5d8a6333cb696572f41167f92d2bff1562f410a41','seed-claim:d2848db6acb2b1b61fadf5a3c1c16d357b631bc2903224691f94fcb444ab242d','seed-claim:d60269f8b76288e266c799173937c8aa1ac0064fb037a7a6bb1f616f03c6822e','seed-claim:e5a001460590e73eea23ef775526270baea81b0f90318e07d1124630c20f6398','seed-claim:f4b709e5a01d6c881160ca2f1dad0cd5ce289f1e3657ca0e894d3cd0bbd0951d')) THEN RAISE EXCEPTION 'PR5.102 provenance collision'; END IF;
  IF coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.products WHERE status='published'),'[]'::jsonb)<>data->'snapshot'->'published_products' OR coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.escape_routes WHERE status='published' AND editorially_approved),'[]'::jsonb)<>data->'snapshot'->'approved_published_routes' THEN RAISE EXCEPTION 'PR5.102 publication drift'; END IF;
  IF NOT has_function_privilege('anon','software_discovery.product_discovery_page(text)','EXECUTE') OR has_table_privilege('anon','software_discovery.claim_evidence','SELECT') THEN RAISE EXCEPTION 'PR5.102 private evidence boundary drift'; END IF;
  FOR op IN SELECT value FROM jsonb_array_elements(data->'guards') LOOP
    EXECUTE format('SELECT coalesce(jsonb_agg(j ORDER BY j::text),''[]''::jsonb) FROM (SELECT to_jsonb(jsonb_populate_record(NULL::software_discovery.%I,r))-''created_at''-''updated_at'' j FROM jsonb_array_elements($1) r) x',op->>'table') INTO input_data USING op->'rows';
    EXECUTE format('SELECT coalesce(jsonb_agg(j ORDER BY j::text),''[]''::jsonb) FROM (SELECT to_jsonb(t)-''created_at''-''updated_at'' j FROM software_discovery.%I t WHERE %s) x',op->>'table',op->>'where') INTO row_data;
    IF input_data<>row_data THEN RAISE EXCEPTION 'PR5.102 retained baseline drift: %',op->>'table'; END IF;
  END LOOP;
  own=data->'ownership';
  FOR replacement IN SELECT value FROM jsonb_array_elements(data->'routeMembershipReplacements') LOOP
    route_slug=replacement->'where'->'escape_route_id'->'$ref'->'where'->>'slug';
    IF NOT (own->'routes' ? route_slug) THEN
      SELECT id INTO route_id FROM software_discovery.escape_routes WHERE slug=route_slug;
      IF route_id IS NOT NULL THEN
        SELECT coalesce(array_agg(value ORDER BY value),'{}') INTO wanted FROM jsonb_array_elements_text(replacement->'desiredProductSlugs');
        IF wanted IS DISTINCT FROM (SELECT coalesce(array_agg(p.slug ORDER BY p.slug),'{}') FROM software_discovery.escape_route_products m JOIN software_discovery.products p ON p.id=m.product_id WHERE m.escape_route_id=route_id) THEN RAISE EXCEPTION 'Existing route membership differs; ownership required: %',route_slug; END IF;
      END IF;
    END IF;
  END LOOP;
  FOR op IN SELECT value FROM jsonb_array_elements(data->'tables') LOOP
    t=op->>'table';
    IF t NOT IN ('evidence_sources','anchors','attributes','problems','audiences','products','product_attributes','product_anchors','product_problems','product_audiences','claim_evidence','product_attribute_evidence','product_anchor_evidence','product_problem_evidence','product_audience_evidence','escape_routes','escape_route_products') THEN RAISE EXCEPTION 'Invalid table'; END IF;
    SELECT string_agg(format('%I',value),',') INTO conflict_cols FROM jsonb_array_elements_text(op->'conflictColumns');
    actual=0; expected=jsonb_array_length(op->'rows');
    FOR raw_row IN SELECT value FROM jsonb_array_elements(op->'rows') LOOP
  input_data=raw_row; row_data='{}';
    FOR k,v IN SELECT * FROM jsonb_each(input_data) LOOP
      IF v ? '$ref' THEN
        target_table=v->'$ref'->>'table';
        IF target_table NOT IN ('products','anchors','attributes','problems','audiences','escape_routes','evidence_sources','claim_evidence') THEN RAISE EXCEPTION 'Invalid reference table'; END IF;
        SELECT key,value INTO STRICT target_key,target_value FROM jsonb_each_text(v->'$ref'->'where');
        IF target_key NOT IN ('slug','seed_key') THEN RAISE EXCEPTION 'Invalid reference key'; END IF;
        EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',target_table,target_key) INTO STRICT resolved_id USING target_value;
        v=to_jsonb(resolved_id);
      END IF;
      row_data=row_data||jsonb_build_object(k,v);
    END LOOP;
      SELECT string_agg(format('%I',key),',' ORDER BY key),string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',key,key),' AND ' ORDER BY key) INTO cols,match_condition FROM jsonb_object_keys(row_data) AS keys(key);
      SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',value,value),' AND ') INTO key_condition FROM jsonb_array_elements_text(op->'conflictColumns');
      allowed=CASE
        WHEN t='evidence_sources' THEN own->'sources' ? (raw_row->>'seed_key')
        WHEN t='products' THEN own->'products' ? (raw_row->>'slug')
        WHEN t='escape_routes' THEN own->'routes' ? (raw_row->>'slug')
        WHEN t='escape_route_products' THEN own->'routes' ? (raw_row->'escape_route_id'->'$ref'->'where'->>'slug')
        WHEN raw_row ? 'product_id' THEN own->'products' ? (raw_row->'product_id'->'$ref'->'where'->>'slug')
        WHEN t IN ('anchors','attributes','problems','audiences') THEN own->'taxonomy'->t ? (raw_row->>'slug')
        ELSE false END;
      IF NOT coalesce(allowed,false) THEN
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s AND NOT (%s))',t,t,key_condition,match_condition) INTO bad USING row_data;
        IF bad THEN RAISE EXCEPTION 'Existing row differs; ownership required: %',t; END IF;
      END IF;
      SELECT string_agg(format('%I=EXCLUDED.%I',key,key),',' ORDER BY key),string_agg(format('target.%I IS DISTINCT FROM EXCLUDED.%I',key,key),' OR ' ORDER BY key) INTO assignments,changed FROM jsonb_object_keys(row_data) AS keys(key) WHERE NOT (op->'conflictColumns' ? key);
      statement=format('INSERT INTO software_discovery.%I AS target (%s) SELECT %s FROM jsonb_populate_record(NULL::software_discovery.%I,$1) source ON CONFLICT (%s) ',t,cols,cols,t,conflict_cols);
      IF assignments IS NULL OR t='claim_evidence' THEN statement=statement||'DO NOTHING';
      ELSE
        IF t IN ('evidence_sources','anchors','attributes','problems','audiences','products','product_attributes','escape_routes','escape_route_products') THEN assignments=assignments||',updated_at=now()'; END IF;
        statement=statement||format('DO UPDATE SET %s WHERE %s',assignments,changed);
      END IF;
      EXECUTE statement USING row_data;
      EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s)',t,t,match_condition) INTO found_row USING row_data;
      IF NOT found_row THEN RAISE EXCEPTION 'Stored row differs from seed: %',t; END IF;
      actual=actual+1;
    END LOOP;
    RAISE NOTICE 'Seed table %: % rows verified',t,actual;
  END LOOP;
  FOR replacement IN SELECT value FROM jsonb_array_elements(data->'evidenceReplacements') LOOP
    t=replacement->>'table';
    IF t NOT IN ('product_attribute_evidence','product_anchor_evidence','product_problem_evidence','product_audience_evidence') THEN RAISE EXCEPTION 'Invalid evidence table'; END IF;
    input_data=replacement->'where'; where_data='{}';
    FOR k,v IN SELECT * FROM jsonb_each(input_data) LOOP
      IF v ? '$ref' THEN
        target_table=v->'$ref'->>'table';
        IF target_table NOT IN ('products','anchors','attributes','problems','audiences','escape_routes','evidence_sources','claim_evidence') THEN RAISE EXCEPTION 'Invalid reference table'; END IF;
        SELECT key,value INTO STRICT target_key,target_value FROM jsonb_each_text(v->'$ref'->'where');
        IF target_key NOT IN ('slug','seed_key') THEN RAISE EXCEPTION 'Invalid reference key'; END IF;
        EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',target_table,target_key) INTO STRICT resolved_id USING target_value;
        v=to_jsonb(resolved_id);
      END IF;
      where_data=where_data||jsonb_build_object(k,v);
    END LOOP;
    SELECT string_agg(format('link.%I IS NOT DISTINCT FROM source.%I',key,key),' AND ') INTO key_condition FROM jsonb_object_keys(where_data) AS keys(key);
    SELECT coalesce(array_agg(value),'{}') INTO desired_keys FROM jsonb_array_elements_text(replacement->'desiredFragmentKeys');
    prefix=replacement->'ownership'->>'fragmentSeedKeyPrefix';
    EXECUTE format('DELETE FROM software_discovery.%I link USING software_discovery.claim_evidence fragment,jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE link.claim_evidence_id=fragment.id AND %s AND left(fragment.seed_key,length($2))=$2 AND NOT(fragment.seed_key=ANY($3))',t,t,key_condition) USING where_data,prefix,desired_keys;
  END LOOP;
  FOR replacement IN SELECT value FROM jsonb_array_elements(data->'routeMembershipReplacements') LOOP
    input_data=replacement->'where'; where_data='{}';
    FOR k,v IN SELECT * FROM jsonb_each(input_data) LOOP
      IF v ? '$ref' THEN
        target_table=v->'$ref'->>'table';
        IF target_table NOT IN ('products','anchors','attributes','problems','audiences','escape_routes','evidence_sources','claim_evidence') THEN RAISE EXCEPTION 'Invalid reference table'; END IF;
        SELECT key,value INTO STRICT target_key,target_value FROM jsonb_each_text(v->'$ref'->'where');
        IF target_key NOT IN ('slug','seed_key') THEN RAISE EXCEPTION 'Invalid reference key'; END IF;
        EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',target_table,target_key) INTO STRICT resolved_id USING target_value;
        v=to_jsonb(resolved_id);
      END IF;
      where_data=where_data||jsonb_build_object(k,v);
    END LOOP;route_id=(where_data->>'escape_route_id')::uuid;
    SELECT coalesce(array_agg(value),'{}') INTO wanted FROM jsonb_array_elements_text(replacement->'desiredProductSlugs');
    DELETE FROM software_discovery.escape_route_products m WHERE m.escape_route_id=route_id AND NOT EXISTS(SELECT 1 FROM software_discovery.products p WHERE p.id=m.product_id AND p.slug=ANY(wanted));
    SELECT count(*) INTO actual FROM software_discovery.escape_route_products WHERE escape_route_id=route_id;
    IF actual<>cardinality(wanted) THEN RAISE EXCEPTION 'Route membership count mismatch'; END IF;
  END LOOP;
  RAISE SQLSTATE 'ZSR01' USING MESSAGE='Rehearsal only';
EXCEPTION WHEN SQLSTATE 'ZSR01' THEN
  RAISE NOTICE 'Rehearsal rolled back; no seed changes persisted';
END $import$;
